from collections import deque

def count_squares(lines):
    def is_square(x, y):
        if lines[y][x] != '+':
            return False
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            if lines[y + dy][x + dx] != '+':
                return False
        return True

    def bfs(x, y):
        queue = deque([(x, y)])
        visited = set()
        while queue:
            x, y = queue.popleft()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            if is_square(x, y):
                for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                    queue.append((x + dx, y + dy))

    count = 0
    for y, line in enumerate(lines):
        for x, char in enumerate(line):
            if char == '+':
                bfs(x, y)
                count += 1
    return count
